-- =====================================================================
-- Jeu de données de démonstration — lycée (généré le 2026-11-18)
--
-- À exécuter sur une base déjà migrée (tables créées par Flyway) et vide de
-- données métier. Rien ici n'est un vrai dossier : noms, notes et règlements
-- sont inventés.
--
--   psql -U lycee -h localhost -d lycee -f donnees-demo.sql
--
-- Contenu : 2 années scolaires (18 élèves par classe sur 8 classes cette année),
-- le personnel, les matières et coefficients, les notes du 1er trimestre,
-- la grille tarifaire, les plans de paiement, les frais, les échéanciers et
-- les règlements déjà encaissés.
-- =====================================================================

BEGIN;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM annee_scolaire) THEN
        RAISE EXCEPTION 'La base contient déjà des données : videz-la avant d''installer le jeu de démonstration (voir le README).';
    END IF;
END $$;








-- Le programme est versionné par année : l'année précédente reprend le même.
SELECT gen_random_uuid(), 'a6aa9479-6e3d-4524-80c9-2f54e6720a38', p.niveau_id, p.matiere_id, p.coefficient,
       now(), 'donnees-demo'
FROM programme_niveau p
WHERE p.annee_scolaire_id = 'cccbe1dc-52ef-4c66-bf58-2e9573037a8a';

-- Appréciations du bulletin, elles aussi réglées année par année (SF-17).
SELECT gen_random_uuid(), a.id, b.portee, b.borne_min, b.borne_max, b.libelle, now(), 'donnees-demo'
FROM annee_scolaire a
CROSS JOIN (VALUES
    ('MATIERE', 0, 5, 'Très insuffisant'),
    ('MATIERE', 5, 8, 'Insuffisant'),
    ('MATIERE', 8, 10, 'Médiocre'),
    ('MATIERE', 10, 12, 'Passable'),
    ('MATIERE', 12, 14, 'Assez bien'),
    ('MATIERE', 14, 16, 'Bien'),
    ('MATIERE', 16, 18, 'Très bien'),
    ('MATIERE', 18, 20, 'Excellent'),
    ('GENERALE', 0, 8, 'Avertissement'),
    ('GENERALE', 12, 14, 'Tableau d''honneur'),
    ('GENERALE', 14, 16, 'Encouragements'),
    ('GENERALE', 16, 20, 'Félicitations')
) AS b (portee, borne_min, borne_max, libelle);















UPDATE inscription SET plan_paiement_id = '4fb02e18-69de-4838-ace6-26baeaa88443' WHERE id IN ('3f7168a5-e705-4d6f-8c51-52b441736870', '771d6be6-f8cc-4bdf-a76e-dbc9f4a17c2e', '342bbcbd-5959-4ad8-b32a-57dde6b61074', 'f595c97c-646f-4c1d-8627-71c048021441', '7490cf64-f835-48a7-bab1-d62c22cdbe9e', '307d940f-3332-4f59-9cb2-8c365903ebb5', '7a92c5e2-fb04-4e00-998e-4140943c7894', 'c1044f69-a6a5-4eb8-b669-1372527a35c6', '3c1f76ca-047c-4fba-a8d8-9720b555d9b7');

-- Un encaissement saisi en double, annulé par l'intendant : le reçu reste, les imputations sont retirées.
DELETE FROM imputation_paiement WHERE paiement_id = '60b70ccb-0b93-4609-be25-0658b6a32842';
UPDATE echeance_eleve e SET montant_paye = COALESCE((SELECT sum(i.montant) FROM imputation_paiement i WHERE i.echeance_eleve_id = e.id), 0) WHERE e.frais_eleve_id IN (SELECT id FROM frais_eleve WHERE inscription_id = '3f7168a5-e705-4d6f-8c51-52b441736870');
UPDATE echeance_eleve e SET statut = CASE WHEN e.montant_paye >= e.montant_du THEN 'PAYEE' WHEN e.date_echeance < DATE '2026-11-17' THEN 'EN_RETARD' WHEN e.montant_paye > 0 THEN 'PARTIEL' ELSE 'A_VENIR' END WHERE e.frais_eleve_id IN (SELECT id FROM frais_eleve WHERE inscription_id = '3f7168a5-e705-4d6f-8c51-52b441736870');
UPDATE paiement SET statut = 'ANNULE', motif_annulation = 'Encaissement saisi deux fois le même jour', annule_par = 'intendant' WHERE id = '60b70ccb-0b93-4609-be25-0658b6a32842';

COMMIT;
